        for _ in range(rng.randint(2 * scale, 10 * scale)):
            variables = rng.sample(range(1, scale + 1), 3)
            clauses.append([v if rng.random() < 0.5 else -v for v in sorted(variables)])
        return {"num_vars": scale, "clauses": clauses}

